SET XACT_ABORT ON;   -- SQL Server: any runtime error rolls back the whole transaction
BEGIN TRANSACTION;
  UPDATE accounts SET balance = balance - 100 WHERE id = @from;
  UPDATE accounts SET balance = balance + 100 WHERE id = @to;
  -- CHECK (balance >= 0) on accounts rejects an overdraft
COMMIT TRANSACTION;

// EF Core: one SaveChanges call is already a transaction.
// Use an explicit transaction when several SaveChanges or raw SQL calls must commit together.
